import{_ as d,l,o as e,c as i,v as o,p as c,x as r,d as s,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"连通分量与桥","description":"","frontmatter":{"title":"连通分量与桥","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bcc-bridge.md","filePath":"cs/bcc-bridge.md","lastUpdated":1789023840000}'),p={name:"cs/bcc-bridge.md"};function E(u,a,B,_,C,m){const t=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="连通分量与桥" tabindex="-1">连通分量与桥 <a class="header-anchor" href="#连通分量与桥" aria-label="Permalink to &quot;连通分量与桥&quot;">​</a></h1><div class="epigraph"><p>无向图上，删掉就使连通支数增加的边是桥；DFS 的 low 值在一次扫描里标出桥、割点与双连通块。</p><footer>—— 据 Tarjan, Depth-First Search and Linear Graph Algorithms, 1972；CLRS 第 22 章整理</footer></div><p>上一课<a href="/cs/dfs-edge-types">DFS 与边分类</a>给出发现/完成时刻，以及有向环当且仅当反向边。无向图上非树边都连祖先，环的存在变成「有没有回边」，但<strong>哪条边是桥、哪个点是割点</strong>时刻不够用。本课不重做括号定理。缺口是 <code>low</code>：子树能摸到的最老祖先发现时刻。后课拓扑假定有向无环，本课先把无向连通的可切边收掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>边 \\(e\\) 是桥：删 \\(e\\) 后连通分量增多。点 \\(v\\) 是割点：删 \\(v\\) 后增多。双连通分量（BCC）：极大的、去掉任一点仍连通的边集块（实现上常按边划分）。缺口是线性算法，不是再 BFS 一遍看连通。</p><p>对树边 \\((u,v)\\)（\\(u\\) 父）：若 \\(v\\) 的子树没有任何回边摸到 \\(u\\) 或更老，则 \\((u,v)\\) 是桥。<code>low[v]=\\min(d[v],</code> 回边端点的 \\(d\\), 子树 <code>low)</code>。割点：根有不少于两棵子树；非根 \\(u\\) 存在孩子 \\(v\\) 使 <code>low[v]\\ge d[u]</code>。</p><p>有向图的强连通分量是另一划分：相互可达。Tarjan / Kosaraju 同为 \\(\\Theta(V+E)\\)。本课点名：有向环落在同一强连通块里；缩点之后才是 DAG。反向边判定环已经够用；SCC 是把环捏成点。</p><h3 id="low-不是距离" tabindex="-1">low 不是距离 <a class="header-anchor" href="#low-不是距离" aria-label="Permalink to &quot;low 不是距离&quot;">​</a></h3><p><code>low</code> 是发现时刻的最小可达，不是无权层数。<a href="/cs/bfs-unweighted">BFS</a> 的距离不管桥。不要用「叶子边都是桥」代替：有回边的叶子边不是桥。</p><p><span class="marginnote">Tarjan 1972 一次 DFS 做双连通与强连通。CLRS 把桥与割点放在 22.2–22.5 的习题与应用。后课拓扑只消费「无向环已能找、有向环已能判」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无向图：DFS 记父，避免把树边当回边扫两遍。维护 <code>d</code> 与 <code>low</code>，回溯时更新父的 <code>low</code>，按不等式报告桥与割点。边栈可弹出一个 BCC。全图 \\(\\Theta(V+E)\\)。</p>',12)),(e(),c(h,null,{default:r(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DFS%5B%22DFS%20%E6%A0%91%20%2B%20%E5%9B%9E%E8%BE%B9%22%5D%20--%3E%20LOW%5B%22low%20%E6%97%B6%E5%88%BB%22%5D%0A%20%20LOW%20--%3E%20BR%5B%22%E6%A1%A5%20%2F%20%E5%89%B2%E7%82%B9%22%5D%0A%20%20LOW%20--%3E%20BCC%5B%22%E5%8F%8C%E8%BF%9E%E9%80%9A%E5%9D%97%22%5D%0A%20%20DIR%5B%22%E6%9C%89%E5%90%91%22%5D%20--%3E%20SCC%5B%22%E5%BC%BA%E8%BF%9E%E9%80%9A%E5%9D%97%20%E2%86%92%20DAG%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>孤立点、重边：重边使「那一条」不是桥。实现要决定平行边是否拆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>桥属于每一个过它的简单环的补：不在环上。BCC 之间恰在割点处粘连，像树。后课最短路、流都不假设双连通；本课只提供分解。也不要把连通分量（无向可达）与 BCC 混名：前者随便 BFS，后者要 <code>low</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算最短路，不写 2-SAT 的蕴含图。有向桥（边连通）更细，不展开。后课默认：无向桥与割点可线性标出；有向环 \\(\\Leftrightarrow\\) 反向边，缩 SCC 得 DAG。拓扑排序是下一课把 DAG 变成线性序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>low</code> 标出桥、割点与双连通块，仍 \\(\\Theta(V+E)\\)。</li><li>有向强连通缩点后才谈拓扑。</li><li>有向环判定仍用反向边，本课不重证。</li><li>出处：Tarjan, 1972；CLRS 第 22 章。</li></ul>',7))])}const D=d(p,[["render",E]]);export{f as __pageData,D as default};
